exercises.exampleInput:
cd AI-SDLC
node --input-type=module <<'EOF'
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
let failed = 0;
for (const skill of ["security-review", "performance-review", "production-rca"]) {
  const doc = JSON.parse(readFileSync(`skills/${skill}/tests/cases.json`, "utf8"));
  const live = doc.cases.filter((c) => c.kind === "live").length;
  for (const c of doc.cases.filter((c) => c.kind === "deterministic")) {
    const r = spawnSync("bash", ["-c", c.input.command], { encoding: "utf8" });
    const e = c.expect;
    const problems = [];
    if (e.exitCode !== undefined && r.status !== e.exitCode) problems.push(`exit ${r.status} != ${e.exitCode}`);
    for (const s of e.stdoutContains || []) if (!r.stdout.includes(s)) problems.push(`stdout lacks ${JSON.stringify(s)}`);
    for (const s of e.stderrContains || []) if (!r.stderr.includes(s)) problems.push(`stderr lacks ${JSON.stringify(s)}`);
    for (const s of e.mustNotContain || []) if ((r.stdout + r.stderr).includes(s)) problems.push(`output contains ${JSON.stringify(s)}`);
    if (problems.length) failed++;
    console.log(`${problems.length ? "FAIL" : "PASS"}  ${skill}  ${c.id}${problems.length ? "  " + problems.join("; ") : ""}`);
  }
  console.log(`      ${skill}: ${live} live case(s) need a model run`);
}
process.exit(failed ? 1 : 0);
EOF
